// resolveManifestSystem resolves and validates the system name both modes
// share: --system wins, the topology's own name is the default, and the result
// becomes a tree segment so it must be a single name.
func resolveManifestSystem(flag string, topo *topology.Topology) (string, error) {
	system := flag
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return "", fmt.Errorf("the topology record names no system; pass --system")
	}
	if err := assertPathSegment("--system", system); err != nil {
		return "", err
	}
	return system, nil
}

// selectManifestComponents derives the model, clones and validates the
// component selection, and warns on components with no scaffold record.
//
// The matched scaffold map is returned alongside the model because both are
// needed downstream and newManifestModel already computed the match: calling
// matchScaffolds again would pair every component twice.
func selectManifestComponents(stderr io.Writer, topo *topology.Topology, scaffolds []template.ScaffoldEntry) (ManifestModel, []ManifestComponent, map[string]template.ScaffoldEntry, error) {
	model := newManifestModel(topo, scaffolds)
	selected := slices.Clone(model.Components)
	for _, c := range selected {
		// From the topology record, which is generated by a build this CLI does
		// not own: a name with a separator in it would render into a directory of
		// its own choosing.
		if err := assertPathSegment("component name", c.Name); err != nil {
			return ManifestModel{}, nil, nil, err
		}
		if c.Dir == "" {
			fmt.Fprintf(stderr, "warning: %s has no scaffold record under the workspace root; its manifests will be generated without an appId or sourcePaths\n", c.Name)
		}
	}
	return model, selected, matchScaffolds(topo.Components, scaffolds), nil
}

