// per component — because the temp root already holds exactly one system and
// no commit needs a repo-relative path. The template's file rules are narrowed
// to manifests only: repo metadata is not Kubernetes.
func renderLocalScaffold(ctx context.Context, opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, lib *template.Library, staging string) error {
	render := func(tmpl *template.Template, skeleton string, dirName string, comp *ManifestComponent) error {
