// renderScaffoldUnits opens each template once and hands it to the mode's
// render: the host first, then one unit per selected component.
func renderScaffoldUnits(lib *template.Library, render func(tmpl *template.Template, skeleton, dirName string, comp *ManifestComponent) error) error {
	units := []struct {
		templateName string
		dirName      string
	}{
		{TemplateDeployHost, HostDirName},
		{TemplateDeployComponent, ""},
	}
	for _, u := range units {
		tmpl, skeleton, err := lib.Open(u.templateName)
		if err != nil {
			return err
		}
		if u.dirName != "" {
			if err := render(tmpl, skeleton, u.dirName, nil); err != nil {
				return err
			}
			continue
		}
		// Component units are selected at render time, so the loop over them
		// lives here rather than in the caller list.
		return errComponentUnits(tmpl, skeleton, render)
	}
	return nil
}

// componentUnits renders the component template once per selected component.
// It is a variable because renderScaffoldUnits has no facts of its own; the
// mode's render closure binds them.
var errComponentUnits = func(tmpl *template.Template, skeleton string, render func(tmpl *template.Template, skeleton, dirName string, comp *ManifestComponent) error) error {
	return fmt.Errorf("renderScaffoldUnits: component units require selectedComponents to be bound")
}

// renderOneUnit renders one unit — the host, or one component — into dest,
// once per environment.
//
// The skeleton is rendered once per environment, because the renderer templates
// paths but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
// the only way to get one directory per environment. mergeRendered then enforces
// that everything outside overlays/ came out identical on every pass.
func renderOneUnit(opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, tmpl *template.Template, skeleton, dest, dirName string, comp *ManifestComponent) error {
	return renderOneUnitWithRules(opts, facts, bindings, tmpl, skeleton, dest, dirName, comp, tmpl.Spec.Files)
}

func renderOneUnitWithRules(opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, tmpl *template.Template, skeleton, dest, dirName string, comp *ManifestComponent, rules []template.FileRule) error {
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}
	for _, env := range facts.Environments {
		values, err := resolveManifestValues(opts, facts, bindings, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", tmpl.Name, dirName, err)
		}

		pass, err := os.MkdirTemp("", "intropy-render-*")
		if err != nil {
			return err
		}
		err = template.RenderFiltered(skeleton, pass, values, rules)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", tmpl.Name, dirName, env, err)
		}
	}
	return nil
}

