func renderScaffoldUnits(opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, lib *template.Library, rulesFor func(*template.Template) []template.FileRule, destFor func(dirName string) string) error {
	hostT, hostSkel, err := lib.Open(TemplateDeployHost)
	if err != nil {
		return err
	}
	if err := renderUnit(opts, facts, bindings, hostT, hostSkel, rulesFor(hostT), destFor(HostDirName), HostDirName, nil); err != nil {
		return err
	}

	compT, compSkel, err := lib.Open(TemplateDeployComponent)
	if err != nil {
		return err
	}
	for _, c := range facts.Selected {
		comp := c
		if err := renderUnit(opts, facts, bindings, compT, compSkel, rulesFor(compT), destFor(c.Name), c.Name, &comp); err != nil {
			return err
		}
	}
