// renderUnit renders one unit — the host, or one component — into dest, in
// two phases.
//
// The base pass renders everything outside overlays/ exactly once, with no
// environment in scope: a value that varies by environment cannot leak into a
// shared file, because referencing .env or .gitops.env there fails the render.
// The overlay passes then render only the overlays/ subtree, once per
// environment with that environment in scope. The renderer templates paths
// but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
// still how one directory per environment comes out.
func renderUnit(opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, tmpl *template.Template, skeleton string, rules []template.FileRule, dest, dirName string, comp *ManifestComponent) error {
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}

	base, err := resolveManifestValues(opts, facts, bindings, tmpl, dirName, comp, "")
	if err != nil {
		return fmt.Errorf("%s for %s: %w", tmpl.Metadata.Name, dirName, err)
	}
	if err := template.RenderFiltered(skeleton, dest, base, baseOnlyRules(rules)); err != nil {
		return fmt.Errorf("render %s for %s: %w\nvalues that vary by environment may only be used under %s", tmpl.Metadata.Name, dirName, err, OverlaysSegment)
	}

	for _, env := range facts.Environments {
		values, err := resolveManifestValues(opts, facts, bindings, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", tmpl.Metadata.Name, dirName, err)
		}
		if err := template.RenderFiltered(skeleton, dest, values, overlaysOnlyRules(rules)); err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", tmpl.Metadata.Name, dirName, env, err)
		}
	}
	return nil
}

// baseOnlyRules narrows a template's file rules to the shared files: the
// overlays subtree is excluded ahead of the template's own rules. The "/**"
// form matches the overlays directory itself, so the walk prunes it before
// any overlay body is parsed — the base pass never evaluates an overlay
// template against env-less values.
func baseOnlyRules(rules []template.FileRule) []template.FileRule {
	out := make([]template.FileRule, 0, len(rules)+1)
	out = append(out, template.FileRule{Path: "overlays/**", When: basePassExclusion})
	return append(out, rules...)
}

// overlaysOnlyRules narrows a template's file rules to the overlays subtree:
// everything outside it is excluded ahead of the template's own rules. The
// "/**" form (not path.Match's "overlays/*", which does not cross
// separators) is what keeps nested overlay files reachable.
func overlaysOnlyRules(rules []template.FileRule) []template.FileRule {
	out := make([]template.FileRule, 0, len(rules)+2)
	out = append(out,
		template.FileRule{Path: "overlays", When: basePassInclusion},
		template.FileRule{Path: "overlays/**", When: basePassInclusion},
		template.FileRule{Path: "**", When: basePassExclusion},
	)
	return append(out, rules...)
}

// The when-values the phase rules use. Both are constants: the phase a rule
// belongs to is decided by its Path, never by the values being rendered.
const (
	basePassInclusion = "true"
	basePassExclusion = "false"
)

