func renderUnit(opts manifestCoreOptions, facts manifestFacts, bindings map[string]map[string]string, tmpl *template.Template, skeleton string, rules []template.FileRule, dest, dirName string, comp *ManifestComponent) error {
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}
	for _, env := range facts.Environments {
		values, err := resolveManifestValues(opts, facts, bindings, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", tmpl.Metadata.Name, dirName, err)
		}

		pass, err := os.MkdirTemp("", "intropy-render-*")
		if err != nil {
			return err
		}
		err = template.RenderFiltered(skeleton, pass, values, rules)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", tmpl.Metadata.Name, dirName, env, err)
		}
	}
	return nil
}

